import { describe, expect, it } from 'vitest';

import { bilibiliLoginFrom, cookiesOfSite, parseCookieFile } from './cookie-file';

// Fake values only. Built with a real tab character (cookies.txt is tab-separated).
const TAB = String.fromCharCode(9);
const line = (domain: string, name: string, value: string): string =>
  [domain, 'TRUE', '/', 'TRUE', '1900000000', name, value].join(TAB);

const NETSCAPE = [
  '# Netscape HTTP Cookie File',
  '# This file was generated by an extension',
  '',
  `#HttpOnly_${line('.bilibili.com', 'SESSDATA', 'fake-sess%2C123')}`,
  line('.bilibili.com', 'buvid3', 'fake-device'),
  line('.bilibili.com', 'bili_jct', 'fake-csrf'),
  line('.example.com', 'SESSDATA', 'other-site'),
].join('\n');

describe('parseCookieFile', () => {
  it('reads cookies.txt, HttpOnly cookies included', () => {
    const cookies = parseCookieFile(NETSCAPE);
    expect(cookies).toHaveLength(4);
    expect(cookies[0]).toEqual({ domain: '.bilibili.com', name: 'SESSDATA', value: 'fake-sess%2C123' });
  });

  it('reads a JSON list of cookies, and skips entries that are not cookies', () => {
    const cookies = parseCookieFile(
      JSON.stringify([{ name: 'SESSDATA', value: 'v', domain: '.bilibili.com', path: '/' }, { name: 'x' }, null, 3]),
    );
    expect(cookies).toEqual([{ name: 'SESSDATA', value: 'v', domain: '.bilibili.com' }]);
  });

  it('ignores a byte-order mark, and Windows line ends', () => {
    expect(parseCookieFile(`\u{FEFF}${NETSCAPE.replace(/\n/g, '\r\n')}`)).toHaveLength(4);
  });
});

describe('cookiesOfSite', () => {
  it('keeps the site and its subdomains, never a look-alike', () => {
    const picked = cookiesOfSite(
      [
        { domain: '.bilibili.com', name: 'a', value: '1' },
        { domain: 'www.bilibili.com', name: 'b', value: '2' },
        { domain: 'notbilibili.com', name: 'c', value: '3' },
        { domain: 'bilibili.com.evil.io', name: 'd', value: '4' },
      ],
      'bilibili.com',
    );
    expect(picked.map((c) => c.name)).toEqual(['a', 'b']);
  });
});

describe('bilibiliLoginFrom', () => {
  it('takes the login and the device id, and nothing else from the file', () => {
    const login = bilibiliLoginFrom(NETSCAPE);
    expect(login).toEqual({ ok: true, cookie: 'SESSDATA=fake-sess%2C123; buvid3=fake-device' });
    expect(JSON.stringify(login)).not.toContain('fake-csrf');
    expect(JSON.stringify(login)).not.toContain('other-site');
  });

  it('works without the device id', () => {
    expect(bilibiliLoginFrom(line('.bilibili.com', 'SESSDATA', 's'))).toEqual({ ok: true, cookie: 'SESSDATA=s' });
  });

  it('says why a file cannot sign the app in', () => {
    expect(bilibiliLoginFrom('')).toEqual({ ok: false, problem: 'not-cookies' });
    expect(bilibiliLoginFrom('hello, this is a letter')).toEqual({ ok: false, problem: 'not-cookies' });
    expect(bilibiliLoginFrom('[{"name": broken')).toEqual({ ok: false, problem: 'not-cookies' });
    expect(bilibiliLoginFrom(line('.example.com', 'SESSDATA', 's'))).toEqual({ ok: false, problem: 'no-site' });
    // Signed out in the browser: the site's cookies, but no login among them.
    expect(bilibiliLoginFrom(line('.bilibili.com', 'buvid3', 'd'))).toEqual({ ok: false, problem: 'signed-out' });
    const blank = [line('.bilibili.com', 'SESSDATA', '   '), line('.bilibili.com', 'buvid3', 'd')].join('\n');
    expect(bilibiliLoginFrom(blank)).toEqual({ ok: false, problem: 'signed-out' });
  });
});
